/**
 * Builds the free lead magnet "Kalendarz zbioru ziół" (A4 landscape PDF) + a preview image
 * from the same herb data the website uses. Run:
 *   bun run scripts/export-herbs.ts /tmp/herbs.json && node scripts/build-lead-magnet.cjs /tmp/herbs.json
 */
const { chromium } = require("playwright");
const fs = require("fs");
const path = require("path");

const root = path.resolve(__dirname, "..");
const herbs = JSON.parse(fs.readFileSync(process.argv[2], "utf8"));
// Static instances (generated by fontTools from the variable fonts) — Chromium embeds variable
// fonts in PDFs at their default (thinnest) instance, so the PDF uses fixed weights instead.
const sfont = (n) => "file://" + path.join(__dirname, ".fonts", n + ".ttf");

const MONTHS = ["I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X", "XI", "XII"];
const PART = { "liść": "L", kwiat: "K", ziele: "Z", "korzeń": "Kr", owoc: "O", "pęd": "P" };
const PART_CLASS = { "liść": "leaf", kwiat: "flower", ziele: "herb", "korzeń": "root", owoc: "fruit", "pęd": "shoot" };

const rows = herbs
  .map((h) => {
    const cells = MONTHS.map((_, i) => {
      const parts = h.harvest.filter((x) => x.months.includes(i + 1));
      if (!parts.length) return `<td></td>`;
      return `<td>${parts.map((p) => `<span class="chip ${PART_CLASS[p.part]}">${PART[p.part]}</span>`).join("")}</td>`;
    }).join("");
    return `<tr><th scope="row"><span class="lat">${h.latin}</span><span class="pl">${h.polish}${h.legal ? " *" : ""}</span></th>${cells}</tr>`;
  })
  .join("");

const html = `<!doctype html><html lang="pl"><head><meta charset="utf-8"><style>
@font-face{font-family:N;src:url(${sfont("N-400-latin")});unicode-range:U+0000-00FF,U+2000-206F,U+2122}
@font-face{font-family:N;src:url(${sfont("N-400-latin-ext")});unicode-range:U+0100-02BA}
@font-face{font-family:N;font-style:italic;src:url(${sfont("N-400i-latin")});unicode-range:U+0000-00FF,U+2000-206F,U+2122}
@font-face{font-family:N;font-style:italic;src:url(${sfont("N-400i-latin-ext")});unicode-range:U+0100-02BA}
@font-face{font-family:M;src:url(${sfont("M-400-latin")});unicode-range:U+0000-00FF,U+2000-206F,U+2122}
@font-face{font-family:M;src:url(${sfont("M-400-latin-ext")});unicode-range:U+0100-02BA}
@font-face{font-family:M;font-weight:600 800;src:url(${sfont("M-600-latin")});unicode-range:U+0000-00FF,U+2000-206F,U+2122}
@font-face{font-family:M;font-weight:600 800;src:url(${sfont("M-600-latin-ext")});unicode-range:U+0100-02BA}
@page{size:A4 landscape;margin:0}
*{box-sizing:border-box;margin:0}
body{width:297mm;height:210mm;overflow:hidden;background:#F7F5EF;color:#182A22;font-family:M,sans-serif;padding:10mm 14mm 8mm;display:flex;flex-direction:column}
header{display:flex;justify-content:space-between;align-items:flex-end;border-bottom:1px solid rgba(24,42,34,.25);padding-bottom:4mm}
h1{font-family:N;font-weight:400;font-size:26pt;letter-spacing:-.02em;line-height:1}
.sub{font-size:9.5pt;color:#4F5A4A;margin-top:2mm}
.brand{text-align:right;font-family:N;font-size:13pt}.brand i{display:block;font-size:9pt;color:#78614D}
table{width:100%;border-collapse:collapse;margin-top:3mm;table-layout:fixed}
thead th{font-family:N;font-weight:400;font-size:9.5pt;padding:1mm 0;color:#78614D;border-bottom:1px solid rgba(24,42,34,.3)}
thead th:first-child{width:56mm;text-align:left}
tbody th{text-align:left;font-weight:400;padding:.55mm 2mm .55mm 0;line-height:1.05}
.lat{font-family:N;font-style:italic;font-size:9.6pt;display:block}.pl{font-size:6.9pt;color:#4F5A4A}
tbody td{border-left:1px solid rgba(24,42,34,.1);text-align:center;vertical-align:middle;padding:.6mm}
tbody tr{border-bottom:1px solid rgba(24,42,34,.08)}
tbody tr:nth-child(odd){background:rgba(221,227,213,.35)}
.chip{display:inline-block;min-width:5.6mm;padding:.3mm .9mm;margin:.2mm;border-radius:.6mm;font-size:6.6pt;font-weight:600;line-height:1.2}
.leaf{background:#263D31;color:#F7F5EF}.flower{background:#B88B66;color:#182A22}.herb{background:#879276;color:#182A22}
.root{background:#78614D;color:#F7F5EF}.fruit{background:#9b3b2a;color:#F7F5EF}.shoot{background:#DDE3D5;color:#182A22;outline:1px solid #879276}
footer{margin-top:auto;display:grid;grid-template-columns:1.1fr 1fr;gap:8mm;font-size:7.2pt;line-height:1.4;color:#2b3a31;padding-top:3mm;border-top:1px solid rgba(24,42,34,.25)}
.legend span{margin-right:2.5mm;white-space:nowrap}
footer p+p{margin-top:1mm}
.disc{color:#4F5A4A}
</style></head><body>
<header><div><h1>Kalendarz zbioru ziół</h1><p class="sub">${herbs.length} roślin, 12 miesięcy — orientacyjne terminy dla Polski. Pogoda i region mogą przesunąć zbiór o kilka tygodni.</p></div>
<div class="brand">Wanda Machocka<i>Blisko natury. Świadomie dla zdrowia.</i></div></header>
<table><thead><tr><th>Roślina</th>${MONTHS.map((m) => `<th>${m}</th>`).join("")}</tr></thead><tbody>${rows}</tbody></table>
<footer><div><p class="legend"><b>Część rośliny:</b> <span><span class="chip leaf">L</span> liść</span><span><span class="chip flower">K</span> kwiat</span><span><span class="chip herb">Z</span> ziele</span><span><span class="chip root">Kr</span> korzeń</span><span><span class="chip fruit">O</span> owoc</span><span><span class="chip shoot">P</span> pęd</span></p>
<p>Zbieraj w suchy dzień, z dala od ruchliwych dróg i pól opryskiwanych. Susz w cieniu, przechowuj w opisanych słoikach do roku.</p>
<p>* Czosnek niedźwiedzi jest w Polsce pod częściową ochroną — zbieraj wyłącznie z upraw.</p></div>
<div><p><b>Nie zbieraj rośliny, której nie jesteś w 100% pewna.</b> Czosnek niedźwiedzi łatwo pomylić z konwalią i zimowitem, dziką marchew ze szczwołem. W razie podejrzenia zatrucia dzwoń pod 112.</p>
<p class="disc">Materiał edukacyjny. Nie zastępuje porady lekarza ani farmaceuty. Przy przyjmowaniu leków, w ciąży i w chorobach przewlekłych skonsultuj stosowanie ziół ze specjalistą.</p></div></footer>
</body></html>`;

(async () => {
  const outDir = path.join(root, "public", "materialy");
  fs.mkdirSync(outDir, { recursive: true });
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1123, height: 794 } });
  const tmp = path.join(require("os").tmpdir(), "wm-kalendarz.html");
  fs.writeFileSync(tmp, html);
  await page.goto("file://" + tmp, { waitUntil: "load" });
  await page.evaluate(() => document.fonts.ready);
  const loaded = await page.evaluate(() => [...document.fonts].filter((f) => f.status === "loaded").length);
  if (loaded < 2) throw new Error("Brand fonts failed to load");
  await page.pdf({ path: path.join(outDir, "kalendarz-zbioru-ziol.pdf"), format: "A4", landscape: true, printBackground: true });
  await page.screenshot({ path: path.join(outDir, "kalendarz-podglad.png") });
  await browser.close();
  console.log("ok");
})();
